// shared contract types - do not edit this file by hand (wrong edits break agents)
#nullable enable
namespace PocketForge.McpTools;

public interface IModelClient
{
    IAsyncEnumerable<string> StreamAsync(IReadOnlyList<(string Role, string Content)> messages, CancellationToken ct);
    Task CancelAsync(CancellationToken ct);
}

public enum LoopEventKind { AssistantDelta, ToolRequested, ToolResult, Denied, Done, Error }

public sealed record LoopEvent(LoopEventKind Kind, string? Delta = null, string? ToolName = null, string? ToolArgs = null, string? Result = null, bool Ok = true, string? Error = null);

public sealed record ToolInfo(string Name, string Description);

public sealed record ToolCallResult(bool Ok, string Output);

public interface IMcpToolClient
{
    Task<IReadOnlyList<ToolInfo>> ListToolsAsync(CancellationToken ct);
    Task<ToolCallResult> CallAsync(string name, string argsJson, CancellationToken ct);
}

public interface IApprovalUi { Task<bool> ApproveAsync(string tool, string argsJson); }
